local function SendEvents()
	for player, outgoing in player_map do
		if outgoing.used > 0 then
			local buff = buffer.create(outgoing.used)
			buffer.copy(buff, 0, outgoing.buff, 0, outgoing.used)

			reliable:FireClient(player, buff, outgoing.inst)

			outgoing.buff = buffer.create(64)
			outgoing.used = 0
			outgoing.size = 64
			table.clear(outgoing.inst)
		end
	end
end

RunService.Heartbeat:Connect(SendEvents)

local reliable_events = table.create(13)
reliable.OnServerEvent:Connect(function(player, buff, inst)
	incoming_buff = buff
	incoming_inst = inst
	incoming_read = 0
	incoming_ipos = 0
	local len = buffer.len(buff)
	while incoming_read < len do
		local id = buffer.readu8(buff, read(1))
		if id == 1 then -- UpdateAvatar
			local value
			local bool_2 = buffer.readu8(incoming_buff, read(1))
			value = {  }
			local len_1 = buffer.readu16(incoming_buff, read(2))
			value["Accessories"] = table.create(len_1)
			for i_1 = 1, len_1 do
				local bool_1 = buffer.readu8(incoming_buff, read(1))
				local val_1
				val_1 = {  }
				val_1["AssetId"] = buffer.readf64(incoming_buff, read(8))
				val_1["AccessoryType"] = {  }
				local len_2 = buffer.readu16(incoming_buff, read(2))
				val_1["AccessoryType"]["EnumType"] = buffer.readstring(incoming_buff, read(len_2), len_2)
				val_1["AccessoryType"]["Value"] = buffer.readu16(incoming_buff, read(2))
				if bit32.btest(bool_1, 0b0000000000000001) then
					val_1["Order"] = buffer.readu16(incoming_buff, read(2))
				else
					val_1["Order"] = nil
				end
				if bit32.btest(bool_1, 0b0000000000000010) then
					val_1["Puffiness"] = buffer.readf32(incoming_buff, read(4))
				else
					val_1["Puffiness"] = nil
				end
				if bit32.btest(bool_1, 0b0000000000000100) then
					val_1["IsLayered"] = bit32.btest(bool_1, 0b0000000000001000)
				else
					val_1["IsLayered"] = nil
				end
				if bit32.btest(bool_1, 0b0000000000010000) then
					val_1["Position"] = Vector3.new(buffer.readf32(incoming_buff, read(4)), buffer.readf32(incoming_buff, read(4)), buffer.readf32(incoming_buff, read(4)))
				else
					val_1["Position"] = nil
				end
				if bit32.btest(bool_1, 0b0000000000100000) then
					val_1["Rotation"] = Vector3.new(buffer.readf32(incoming_buff, read(4)), buffer.readf32(incoming_buff, read(4)), buffer.readf32(incoming_buff, read(4)))
				else
					val_1["Rotation"] = nil
				end
				if bit32.btest(bool_1, 0b0000000001000000) then
					val_1["Scale"] = Vector3.new(buffer.readf32(incoming_buff, read(4)), buffer.readf32(incoming_buff, read(4)), buffer.readf32(incoming_buff, read(4)))
				else
					val_1["Scale"] = nil
				end
				value["Accessories"][i_1] = val_1
			end
			value["Emotes"] = {  }
			if not bit32.btest(bool_2, 0b0000000000000001) then
				for _ = 1, buffer.readu16(incoming_buff, read(2)) + 1 do
					local key_1
					local val_2
					local len_3 = buffer.readu16(incoming_buff, read(2))
					key_1 = buffer.readstring(incoming_buff, read(len_3), len_3)
					local len_4 = buffer.readu16(incoming_buff, read(2))
					val_2 = table.create(len_4)
					for i_2 = 1, len_4 do
						local val_3
						val_3 = buffer.readf64(incoming_buff, read(8))
						val_2[i_2] = val_3
					end
					value["Emotes"][key_1] = val_2
				end
			end
			local len_5 = buffer.readu16(incoming_buff, read(2))
